module bench/registry v1.0.0;
import "io/stdout" take Stdout;
import "os/environment" take Environment;
import "strings/parse" take ParsedInt;
object Job {
    Job();
    async run() is int { 7; }
}
async main() is int {
    let count=ParsedInt(Environment().variable("COUNT")).value();
    for 0..count -> i {
        let future=spawn Job().run();
        confirm (await future)==7 && (await future)==7 else panic "cached outcome";
    }
    Stdout().writeln("ok "+count.string());
    0;
}

